-- GRAIN: one row per organization (LEI is unique)
-- SPINE_ENTITY: organization  (natural_key: LEI)
-- Generated by scripts/generate_staging_models.py from SOURCE_REGISTRY -- deterministic,
-- no LLM. Casts kept as landed (TEXT) -- add explicit type casts by hand once each
-- column's real type is confirmed; this generator has no semantic type knowledge.
--
-- FIXED 2026-08-06: the generator assumed flat column names (ENTITY_LEGAL_NAME,
-- ENTITY_LEGAL_ADDRESS, ...) but the live landing table carries GLEIF's raw
-- XML element paths instead (Entity.LegalName, Entity.LegalAddress.City, ...),
-- so this view had been erroring on every query -- confirmed dead: nothing in
-- the dbt project or the Python codebase reads this model, it just sat broken.
-- Address fields are rebuilt from GLEIF's split address sub-fields (no single
-- flat address field exists in the source); entity_country is a judgment call
-- -- GLEIF has no single top-level "entity country" field, so this uses the
-- legal address's country (not headquarters, which can differ for redomiciled
-- entities) as the closest match to the old column's apparent intent.

with source as (

    select * from {{ source('ripple_raw', 'INTL_GLEIF') }}

),

renamed as (

    select
        "LEI" as lei,
        "Entity.LegalName" as entity_legal_name,
        array_to_string(array_construct_compact(
            nullif(trim("Entity.LegalAddress.FirstAddressLine"), ''),
            nullif(trim("Entity.LegalAddress.City"), ''),
            nullif(trim("Entity.LegalAddress.Region"), ''),
            nullif(trim("Entity.LegalAddress.PostalCode"), ''),
            nullif(trim("Entity.LegalAddress.Country"), '')
        ), ', ') as entity_legal_address,
        array_to_string(array_construct_compact(
            nullif(trim("Entity.HeadquartersAddress.FirstAddressLine"), ''),
            nullif(trim("Entity.HeadquartersAddress.City"), ''),
            nullif(trim("Entity.HeadquartersAddress.Region"), ''),
            nullif(trim("Entity.HeadquartersAddress.PostalCode"), ''),
            nullif(trim("Entity.HeadquartersAddress.Country"), '')
        ), ', ') as entity_headquarters_address,
        "Entity.LegalJurisdiction" as entity_legal_jurisdiction,
        "Entity.LegalAddress.Country" as entity_country,
        "Entity.RegistrationAuthority.RegistrationAuthorityID" as registration_authority_id,
        "Registration.RegistrationStatus" as registration_status,
        "Registration.InitialRegistrationDate" as initial_registration_date,
        "Registration.LastUpdateDate" as last_update_date,
        "Registration.NextRenewalDate" as next_renewal_date,
        _INGESTED_AT as _loaded_at,
        'https://leidata.gleif.org/api/v1/concatenated-files/lei2/latest?format=xml' as _source_url,
    'ENT_' || LEFT(MD5('LEI' || '|' || (CASE WHEN LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("LEI"), '[^0-9A-Za-z]', ''))) = 20 THEN UPPER(REGEXP_REPLACE(TO_VARCHAR("LEI"), '[^0-9A-Za-z]', '')) ELSE NULL END)), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

    from source

)

select * from renamed
qualify row_number() over (partition by lei order by _loaded_at desc) = 1
